import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster } from "./tokens.stylex";
import { Dialog } from "./dialog";

const styles = stylex.create({
  lock: {
    borderRadius: raster.radiusSm,
    boxShadow: "none",
  },
});

export interface AlertDialogProps extends Omit<React.DialogHTMLAttributes<HTMLDialogElement>, "open"> {
  open: boolean;
  onClose?: () => void;
}

/**
 * A native <dialog> that requires an explicit answer. Escape and
 * light dismiss are disabled.
 */
export function AlertDialog({ open, onClose, ...props }: AlertDialogProps) {
  return (
    <Dialog
      open={open}
      onClose={onClose}
      role="alertdialog"
      onCancel={(e) => e.preventDefault()}
      extraStyles={[styles.lock]}
      {...props}
    />
  );
}

export {
  DialogTitle as AlertDialogTitle,
  DialogBody as AlertDialogBody,
  DialogActions as AlertDialogActions,
} from "./dialog";

import * as stylex from "@stylexjs/stylex";

/**
 * StyleX vars alias Raster CSS custom properties. Not a second scale.
 * Values live in packages/core/css/tokens.css (generated from src/tokens.ts).
 */
export const raster = stylex.defineVars({
  paper: "var(--bg)",
  ink: "var(--text)",
  gray: "var(--text-secondary)",
  accent: "var(--accent)",
  divider: "var(--divider)",
  dividerSubtle: "var(--divider-subtle)",
  tableAlt: "var(--table-alt)",
  gridLine: "var(--grid-line)",
  radiusSm: "var(--radius-sm)",
  radius: "var(--radius)",
  radiusChrome: "var(--radius-chrome)",
  radiusIn: "var(--radius-in)",
  pad: "var(--pad)",
  gutter: "var(--gutter)",
  module: "var(--grid-size)",
  gridImage: "var(--grid-image)",
  gridPos: "var(--grid-pos)",
  hit: "var(--hit)",
  controlH: "var(--control-h)",
  controlFs: "var(--control-fs)",
  controlLabel: "var(--control-label)",
  durationSnap: "var(--duration-snap)",
  duration: "var(--duration)",
  durationConfirm: "var(--duration-confirm)",
  ease: "var(--ease)",
  transition: "var(--transition)",
  textScale: "var(--text-scale)",
  hairline: "1px",
});

/** Inter stack. Same as body in base.css. Not a token var — @font-face stays CSS. */
export const rasterFont =
  "Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif";

export const rasterMono = "ui-monospace, SFMono-Regular, Menlo, monospace";

/** Compile-time media keys. StyleX only folds defineConsts, not plain strings. */
export const mq = stylex.defineConsts({
  phone: "@media (max-width: 640px)",
  mobileGrid: "@media (max-width: 480px)",
  at900: "@media (min-width: 900px)",
  at899: "@media (max-width: 899px)",
  rail: "@media (min-width: 1024px)",
  wide: "@media (min-width: 1440px)",
  reduce: "@media (prefers-reduced-motion: reduce)",
  touch: "@media (hover: none)",
});

/** Phone recut (≤640). Desktop stays the poster. */
export const phone = mq.phone;

/** Mobile grid (≤480). */
export const mobileGrid = mq.mobileGrid;

/** Catalog rail. */
export const rail = mq.rail;

/** Wide catalog. */
export const wide = mq.wide;

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster, phone as phoneMq } from "./tokens.stylex";
import { rs } from "./rs";

/** StyleX cannot read a string const from a defineVars file; keep the token import. */
const phone = "@media (max-width: 640px)" as typeof phoneMq;

export interface DialogProps extends Omit<React.DialogHTMLAttributes<HTMLDialogElement>, "open"> {
  open: boolean;
  onClose?: () => void;
  /** Extra StyleX leaves merged after the dialog frame (command palette). */
  extraStyles?: unknown[];
}

export const dialogStyles = stylex.create({
  frame: {
    boxSizing: "border-box",
    maxWidth: {
      default: 320,
      [phone]: "calc(100vw - 32px)",
    },
    width: {
      default: null,
      [phone]: "calc(100vw - 32px)",
    },
    borderWidth: raster.hairline,
    borderStyle: "solid",
    borderColor: raster.divider,
    borderRadius: raster.radiusSm,
    padding: {
      default: 20,
      [phone]: "24px 20px",
    },
    backgroundColor: raster.paper,
    color: raster.ink,
    boxShadow: "none",
    "::backdrop": {
      backgroundColor: "rgba(0,0,0,0.25)",
    },
  },
  title: {
    display: "block",
    fontSize: {
      default: 15,
      [phone]: 18,
    },
    fontWeight: 600,
    letterSpacing: "-0.01em",
    color: raster.ink,
    marginBottom: {
      default: 6,
      [phone]: 10,
    },
  },
  body: {
    fontSize: {
      default: 13.5,
      [phone]: 16,
    },
    color: raster.gray,
    letterSpacing: "-0.01em",
    lineHeight: 1.55,
    marginTop: 0,
    marginRight: 0,
    marginBottom: {
      default: 16,
      [phone]: 20,
    },
    marginLeft: 0,
  },
  actions: {
    display: "flex",
    justifyContent: "flex-end",
    flexDirection: {
      default: "row",
      [phone]: "column",
    },
    alignItems: {
      default: "flex-end",
      [phone]: "stretch",
    },
    gap: {
      default: 8,
      [phone]: 10,
    },
  },
});

/**
 * A native <dialog>. Focus trapping, Escape, and the backdrop come
 * from the platform.
 */
export function Dialog({
  open,
  onClose,
  className,
  style,
  children,
  extraStyles,
  ...props
}: DialogProps) {
  const ref = React.useRef<HTMLDialogElement>(null);

  React.useEffect(() => {
    const dialog = ref.current;
    if (!dialog) return;
    if (open && !dialog.open) dialog.showModal();
    else if (!open && dialog.open) dialog.close();
  }, [open]);

  const sx = rs(["rs-dialog", className], dialogStyles.frame, ...(extraStyles ?? []));
  return (
    <dialog
      ref={ref}
      className={sx.className}
      style={{ ...sx.style, ...style }}
      onClose={() => onClose?.()}
      {...props}
    >
      {children}
    </dialog>
  );
}

export function DialogTitle({ className, style, ...props }: React.HTMLAttributes<HTMLSpanElement>) {
  const sx = rs(["rs-dialog-title", className], dialogStyles.title);
  return <span {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
}

export function DialogBody({ className, style, ...props }: React.HTMLAttributes<HTMLParagraphElement>) {
  const sx = rs(["rs-dialog-body", className], dialogStyles.body);
  return <p {...props} className={sx.className} style={{ ...sx.style, ...style }} />;
}

export function DialogActions({ className, style, children, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  const sx = rs(["rs-dialog-actions", className], dialogStyles.actions);
  return (
    <div {...props} className={sx.className} style={{ ...sx.style, ...style }}>
      {React.Children.map(children, (child) => {
        if (!React.isValidElement<{ style?: React.CSSProperties }>(child)) return child;
        return React.cloneElement(child, {
          style: { ...child.props.style, borderRadius: 0 },
        });
      })}
    </div>
  );
}

import type { CSSProperties } from "react";
import * as stylex from "@stylexjs/stylex";
import { cx } from "./cx";

type StyleXProps = { className?: string; style?: CSSProperties };

/** Merge Raster class names with StyleX props. CSS-first classes stay on the node. */
export function rs(classNames: Array<string | false | null | undefined>, ...styles: unknown[]): StyleXProps {
  const sx = (stylex.props as (...args: unknown[]) => StyleXProps)(...styles);
  return {
    className: cx(...classNames, sx.className),
    style: sx.style,
  };
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Dialog: one question, two equal actions, no third option.
   Nested actions use Steve’s innerRadius of the frame. ── */
.rs-dialog{
  --rs-out:var(--radius-sm);
  --rs-gap:20px;
  --rs-in:max(0px,calc(var(--rs-out) - var(--rs-gap)));
  max-width:320px;
  border:1px solid var(--divider);
  border-radius:var(--rs-out);
  padding:var(--rs-gap);
  background:var(--bg);
  box-shadow:none
}
dialog.rs-dialog{color:var(--text)}
dialog.rs-dialog::backdrop{background:rgba(0,0,0,0.25)}
.rs-dialog-title{display:block;font-size:15px;font-weight:600;letter-spacing:-.01em;color:var(--text);margin-bottom:6px}
.rs-dialog-body{font-size:13.5px;color:var(--text-secondary);letter-spacing:-.01em;line-height:1.55;margin:0 0 16px}
.rs-dialog-actions{display:flex;justify-content:flex-end;gap:8px}
.rs-dialog .rs-btn-primary,.rs-dialog .rs-btn-ghost{border-radius:var(--rs-in)}
